SELECT cs.id, cs.status, cs.ai_summary, cs.create_time, cs.update_time, cs.user_id, u.username AS username, u.avatar AS avatar, u.age AS age FROM consultation_session cs LEFT JOIN user u ON cs.user_id = u.id
AND cs.update_time >= #{queryDTO.queryDate} AND cs.update_time < DATE_ADD(#{queryDTO.queryDate}, INTERVAL 1 DAY)
AND cs.status = #{queryDTO.status}
AND cs.doctor_id = #{doctorId}
ORDER BY cs.update_time DESC

SELECT *
FROM consultation_session
WHERE user_id = #{userId}
  AND update_time >= #{startOfDay}
  AND update_time <= #{endOfDay}

SELECT *
FROM consultation_session
WHERE update_time BETWEEN #{startTime} AND #{endTime}

SELECT * FROM chat_message WHERE id IN
#{id}
ORDER BY create_time ASC
